//  StockCard.swift — the film and paper cards (PRD/PRD-胶片指南卡片与风格.md §3).
//
//  A card is read-only and costs no engine work (PRD R1): everything on it is
//  in `StockCatalog.json` already, generated by `Tools/gen-catalog.py`.
//
//  **No package photographs** (PRD §3.3, Q4). The art is the designer's
//  illustration when the bundle has one, and otherwise a drawing by type —
//  the same colour coding the illustrations use, with only the speed on it.
//
//  Shown beside a row after the pointer has rested on it for half a second
//  (`StockCardHover`), and from the section's "•••" for the stock in use.

import AppKit
import SwiftUI

struct StockCard: View {
    let stock: Stock
    let catalog: StockCatalog
    /// The paper list's fast-flip note, which used to be the row's whole
    /// tooltip; nil when the fast flip is off or the paper has no baked table.
    var fastFlipLine: String? = nil

    static let width: CGFloat = 280

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            StockArt(stock: stock)
                .frame(height: 88)
            VStack(alignment: .leading, spacing: 2) {
                Text(stock.name)
                    .font(Theme.Font.body.weight(.semibold))
                    .foregroundStyle(Theme.Ink.primary)
                Text(stock.kindLine)
                    .font(Theme.Font.meta)
                    .foregroundStyle(Theme.Ink.tertiary)
            }
            summary
            if !stock.scenes.isEmpty {
                FlowLayout(spacing: 4, lineSpacing: 4) {
                    ForEach(stock.scenes) { scene in
                        Text(scene.title)
                            .font(Theme.Font.meta)
                            .foregroundStyle(Theme.Ink.secondary)
                            .padding(.horizontal, 6)
                            .frame(height: 15)
                            .background(Theme.pill, in: Capsule())
                    }
                }
            }
            traits
            facts
        }
        .padding(12)
        .frame(width: Self.width, alignment: .leading)
        .background(Theme.card)
    }

    @ViewBuilder private var summary: some View {
        if let text = stock.guide?.summary {
            VStack(alignment: .leading, spacing: 3) {
                Text(text)
                    .font(Theme.Font.body)
                    .foregroundStyle(Theme.Ink.secondary)
                    .fixedSize(horizontal: false, vertical: true)
                // The owner has not approved the copy yet (PRD Q1). Saying so
                // on the card is cheaper than shipping a sentence nobody read.
                if stock.guide?.isDraft ?? true {
                    Text(L("Draft copy", zh: "文案待确认"))
                        .font(Theme.Font.meta)
                        .foregroundStyle(Theme.accent)
                }
            }
        }
    }

    /// The measured dots (PRD §3.5). Absent until `engine/tests/stock_traits.py`
    /// has run, and then each row only where a number exists.
    @ViewBuilder private var traits: some View {
        if let t = stock.traits {
            VStack(alignment: .leading, spacing: 3) {
                TraitRow(title: L("Contrast", zh: "反差"), trait: t.contrast)
                // A silver stock has no saturation to speak of.
                if !stock.isMonochrome {
                    TraitRow(title: L("Saturation", zh: "饱和度"), trait: t.saturation)
                }
                if stock.isFilm {
                    TraitRow(title: L("Latitude", zh: "宽容度"), trait: t.latitude)
                    TraitRow(title: L("Grain", zh: "颗粒"), trait: t.grain)
                    // Scheme A (PRD Q3): the dots are what the engine renders,
                    // and for colour negatives that is one model today.
                    if stock.isColourNegative {
                        Text(L("Colour negatives render with similar grain in this version.",
                               zh: "当前版本彩色负片颗粒相近。"))
                            .font(Theme.Font.meta)
                            .foregroundStyle(Theme.Ink.tertiary)
                    }
                }
            }
        }
    }

    /// The lines that are facts about the catalogue rather than about the look.
    @ViewBuilder private var facts: some View {
        VStack(alignment: .leading, spacing: 2) {
            ForEach(factLines, id: \.self) { line in
                Text(line)
                    .font(Theme.Font.meta)
                    .foregroundStyle(Theme.Ink.tertiary)
                    .fixedSize(horizontal: false, vertical: true)
            }
        }
    }

    private var factLines: [String] {
        var lines: [String] = []
        if stock.isFilm {
            if stock.isPositive {
                lines.append(L("Scanned directly, not printed.", zh: "直接扫描，不经相纸。"))
            } else if let paper = stock.targetPrint.flatMap(catalog.stock) {
                lines.append(L("Default paper: ", zh: "默认相纸：") + paper.name)
            }
            if let formats = stock.formats, !formats.isEmpty {
                lines.append(L("Formats: ", zh: "画幅：") + formats.joined(separator: " · "))
            }
        } else {
            let films = catalog.films(printingOn: stock.id)
            if !films.isEmpty {
                lines.append(L("The default paper of: ", zh: "默认搭配的胶片：")
                             + films.map(\.name).joined(separator: L(", ", zh: "、")))
            }
            if let fastFlipLine, !fastFlipLine.isEmpty { lines.append(fastFlipLine) }
        }
        return lines
    }
}

/// One trait as five dots. A trait without a level (not measured, or the
/// range had nothing to spread over) is left out rather than drawn as zero.
private struct TraitRow: View {
    let title: String
    let trait: StockTrait?

    var body: some View {
        if let level = trait?.level {
            HStack(spacing: 6) {
                Text(title)
                    .font(Theme.Font.meta)
                    .foregroundStyle(Theme.Ink.secondary)
                    .frame(width: 52, alignment: .leading)
                HStack(spacing: 3) {
                    ForEach(1...5, id: \.self) { i in
                        Circle()
                            .fill(i <= level ? Theme.Ink.primary : Theme.pill)
                            .frame(width: 6, height: 6)
                    }
                }
            }
            // The dots are relative; the number is what was measured (PRD Q12).
            .help(String(format: "%.3g", trait?.value ?? 0))
            .accessibilityElement(children: .ignore)
            .accessibilityLabel("\(title) \(level)/5")
        }
    }
}

/// The illustration, or a drawing by type when the bundle has none.
struct StockArt: View {
    let stock: Stock

    var body: some View {
        if let url = stock.artURL, let image = NSImage(contentsOf: url) {
            Image(nsImage: image)
                .resizable()
                .aspectRatio(contentMode: .fit)
                .frame(maxWidth: .infinity)
                .accessibilityHidden(true)
        } else {
            placeholder
        }
    }

    /// The type's colour and the speed, nothing else (PRD Q4: no logos).
    private var placeholder: some View {
        RoundedRectangle(cornerRadius: 6, style: .continuous)
            .fill(LinearGradient(colors: [tint, tint.opacity(0.55)],
                                 startPoint: .topLeading, endPoint: .bottomTrailing))
            .overlay(alignment: .bottomLeading) {
                Text(stock.iso.map { "\($0)" } ?? (stock.isPaper ? L("Paper", zh: "相纸") : ""))
                    .font(.system(size: 22, weight: .bold, design: .rounded))
                    .foregroundStyle(Color.white.opacity(0.85))
                    .padding(10)
            }
            .accessibilityHidden(true)
    }

    private var tint: Color {
        if stock.isPaper { return stock.isMonochrome ? Color(white: 0.55) : Color(hex: 0x8C7B6A) }
        if stock.isMonochrome { return Color(white: 0.35) }
        if stock.isPositive { return Color(hex: 0x3D6E9E) }
        if stock.isCine { return Color(hex: 0x7A3B3B) }
        return Color(hex: 0xC2782F)
    }
}

/// Shows a card beside its row once the pointer has rested there for half a
/// second.
///
/// The delay is also what keeps cards from flashing while the list scrolls
/// under a still pointer: each row passes in far less than 0.5 s, and leaving
/// a row cancels its pending card. The card holds no control, so it has
/// nothing to take keyboard focus with.
struct StockCardHover: ViewModifier {
    let card: AnyView?
    @State private var shown = false
    @State private var pending: Task<Void, Never>?

    func body(content: Content) -> some View {
        if let card {
            content
                .onHover { inside in
                    pending?.cancel()
                    if inside {
                        pending = Task { @MainActor in
                            try? await Task.sleep(for: .milliseconds(500))
                            guard !Task.isCancelled else { return }
                            shown = true
                        }
                    } else {
                        shown = false
                    }
                }
                .onDisappear { pending?.cancel(); shown = false }
                .popover(isPresented: $shown, arrowEdge: .trailing) { card }
        } else {
            content
        }
    }
}
